    while (k < removals.length && removals[k][0] < end) {
      const [cutStart, cutEnd] = removals[k];
      if (cutStart > cursor) result.push([cursor, cutStart]);
      cursor = Math.max(cursor, cutEnd);
      if (cursor >= end) break;
      k++;
    }
    if (cursor < end) result.push([cursor, end]);
    j = k;
  }

  return result;
}

export function parseRanges(text) {
  if (typeof text !== 'string') {
    throw new TypeError('Expected a string');
  }
  if (text.trim() === '') return [];

  const values = new Set();
  for (const item of text.split(',')) {
    const match = /^([+-]?\d+)(?:\s*\.\.\s*([+-]?\d+))?$/.exec(item.trim());
    if (!match) {
      throw new RangeError('Invalid integer or range syntax');
    }

    const start = Number(match[1]);
    const end = match[2] === undefined ? start : Number(match[2]);
    if (!Number.isSafeInteger(start) || !Number.isSafeInteger(end)) {
      throw new RangeError('Integers must be safe');
    }
    if (start > end) {
      throw new RangeError('Descending ranges are not allowed');
    }
    const span = end - start;
    if (span >= 1000) {
      throw new RangeError('Ranges may contain at most 1000 members');
    }

    for (let offset = 0; offset <= span; offset++) {
      values.add(start + offset);
    }
  }

  return [...values].sort((a, b) => a - b);
}

