export function subtractIntervals(base, cuts) {
  function normalize(intervals) {
    if (!Array.isArray(intervals)) throw new RangeError('Expected an array of intervals');
    const sorted = [];
    for (const pair of intervals) {
      if (!Array.isArray(pair) || pair.length !== 2 ||
          !Number.isFinite(pair[0]) || !Number.isFinite(pair[1]) ||
          pair[0] > pair[1]) {
        throw new RangeError('Invalid interval');
      }
      if (pair[0] < pair[1]) sorted.push([pair[0], pair[1]]);
    }
    sorted.sort((a, b) => a[0] - b[0]);
    const merged = [];
    for (const pair of sorted) {
      const last = merged[merged.length - 1];
      if (last && pair[0] <= last[1]) {
        last[1] = Math.max(last[1], pair[1]);
      } else {
        merged.push(pair);
      }
    }
    return merged;
  }

  const bases = normalize(base);
  const removals = normalize(cuts);
  const result = [];
  let j = 0;

  for (const [start, end] of bases) {
    let cursor = start;
    while (j < removals.length && removals[j][1] <= start) j++;
    while (j < removals.length && removals[j][0] < end) {
      const [cutStart, cutEnd] = removals[j];
      if (cutStart > cursor) result.push([cursor, cutStart]);
      cursor = Math.max(cursor, cutEnd);
      if (cursor >= end) break;
      j++;
    }
    if (cursor < end) result.push([cursor, end]);
  }
  return result;
}

export function subtractIntervals(base, cuts) {
  function normalize(intervals) {
    if (!Array.isArray(intervals)) {
      throw new RangeError('Expected an array of interval pairs');
    }

    const sorted = [];
    for (const pair of intervals) {
      if (!Array.isArray(pair) || pair.length !== 2) {
        throw new RangeError('Expected a [start, end] pair');
      }
      const [start, end] = pair;
      if (!Number.isFinite(start) || !Number.isFinite(end) || start > end) {
        throw new RangeError('Endpoints must be finite numbers with start <= end');
      }
      if (start < end) sorted.push([start, end]);
    }

    sorted.sort((a, b) => a[0] - b[0]);
    const merged = [];
    for (const interval of sorted) {
      const last = merged[merged.length - 1];
      if (last && interval[0] <= last[1]) {
        last[1] = Math.max(last[1], interval[1]);
      } else {
        merged.push(interval);
      }
    }
    return merged;
  }

  const bases = normalize(base);
  const exclusions = normalize(cuts);
  const result = [];
  let cutIndex = 0;

  for (const [start, end] of bases) {
    let cursor = start;
    while (cutIndex < exclusions.length && exclusions[cutIndex][1] <= cursor) {
      cutIndex++;
    }

    while (cutIndex < exclusions.length && exclusions[cutIndex][0] < end) {
      const [cutStart, cutEnd] = exclusions[cutIndex];
      if (cutStart > cursor) result.push([cursor, cutStart]);
      cursor = Math.max(cursor, cutEnd);
      if (cursor >= end) break;
      cutIndex++;
    }

    if (cursor < end) result.push([cursor, end]);
  }

  return result;
}
